CREATE TABLE `collection_tasks` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`status` ENUM('draft','scheduled','queued','leased','running','parsing','validating','persisted','retry_scheduled','blocked_login','blocked_captcha','blocked_robots','rate_limited','succeeded','succeeded_empty','completed_with_warnings','failed_terminal','dead_letter','manually_replayed') NOT NULL,`coverage_status` ENUM('complete','partial','insufficient') NULL,`priority` ENUM('low','normal','high','critical') NOT NULL,`scheduled_at` DATETIME(3) NOT NULL,`available_at` DATETIME(3) NOT NULL,`leased_at` DATETIME(3) NULL,`lease_owner` VARCHAR(160) CHARACTER SET ascii NULL,`lease_token_hash` BINARY(32) NULL,`lease_expires_at` DATETIME(3) NULL,`started_at` DATETIME(3) NULL,`finished_at` DATETIME(3) NULL,`attempt_count` TINYINT UNSIGNED NOT NULL DEFAULT 0,`successful_subquery_count` INT UNSIGNED NOT NULL DEFAULT 0,`failed_subquery_count` INT UNSIGNED NOT NULL DEFAULT 0,`blocked_subquery_count` INT UNSIGNED NOT NULL DEFAULT 0,`available_result_count` INT UNSIGNED NOT NULL DEFAULT 0,`missing_fields_json` JSON NOT NULL,`last_error_code` VARCHAR(80) CHARACTER SET ascii NULL,`rate_limit_reset_at` DATETIME(3) NULL,`replay_of_task_id` CHAR(36) CHARACTER SET ascii NULL,`replay_reason` VARCHAR(500) NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`version` INT UNSIGNED NOT NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),KEY `idx_collection_task_scope_status` (`organization_id`,`workspace_id`,`status`,`updated_at`),KEY `idx_collection_task_schedule` (`status`,`available_at`,`priority`),KEY `idx_collection_task_lease_expiry` (`lease_expires_at`),KEY `idx_collection_task_trace` (`trace_id`),KEY `idx_collection_task_replay` (`replay_of_task_id`),CONSTRAINT `fk_collection_task_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),CONSTRAINT `fk_collection_task_workspace` FOREIGN KEY (`workspace_id`) REFERENCES `workspaces` (`id`),CONSTRAINT `fk_collection_task_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),CONSTRAINT `fk_collection_task_replay` FOREIGN KEY (`replay_of_task_id`) REFERENCES `collection_tasks` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `collection_subqueries` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`task_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`provider_id` CHAR(36) CHARACTER SET ascii NOT NULL,`ordinal` SMALLINT UNSIGNED NOT NULL,`target_json` JSON NOT NULL,`is_required` TINYINT(1) NOT NULL,`status` ENUM('pending','running','succeeded','succeeded_empty','failed','blocked') NOT NULL,`available_result_count` INT UNSIGNED NOT NULL DEFAULT 0,`missing_fields_json` JSON NOT NULL,`error_code` VARCHAR(80) CHARACTER SET ascii NULL,`retryable` TINYINT(1) NOT NULL DEFAULT 0,`started_at` DATETIME(3) NULL,`finished_at` DATETIME(3) NULL,`version` INT UNSIGNED NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_collection_subquery_ordinal` (`task_id`,`ordinal`),KEY `idx_collection_subquery_scope_status` (`organization_id`,`workspace_id`,`status`),KEY `idx_collection_subquery_provider` (`provider_id`,`status`),CONSTRAINT `fk_collection_subquery_task` FOREIGN KEY (`task_id`) REFERENCES `collection_tasks` (`id`) ON DELETE CASCADE,CONSTRAINT `fk_collection_subquery_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),CONSTRAINT `fk_collection_subquery_workspace` FOREIGN KEY (`workspace_id`) REFERENCES `workspaces` (`id`),CONSTRAINT `fk_collection_subquery_provider` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `collection_task_attempts` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`task_id` CHAR(36) CHARACTER SET ascii NOT NULL,`attempt_number` TINYINT UNSIGNED NOT NULL,`worker_id` VARCHAR(160) CHARACTER SET ascii NOT NULL,`status` ENUM('leased','running','succeeded','retry_scheduled','blocked_login','blocked_captcha','blocked_robots','rate_limited','failed_terminal','dead_letter') NOT NULL,`error_code` VARCHAR(80) CHARACTER SET ascii NULL,`leased_at` DATETIME(3) NOT NULL,`lease_expires_at` DATETIME(3) NOT NULL,`started_at` DATETIME(3) NULL,`finished_at` DATETIME(3) NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_collection_task_attempt` (`task_id`,`attempt_number`),KEY `idx_collection_attempt_trace` (`trace_id`),CONSTRAINT `fk_collection_attempt_task` FOREIGN KEY (`task_id`) REFERENCES `collection_tasks` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `collection_dead_letters` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`task_id` CHAR(36) CHARACTER SET ascii NOT NULL,`attempt_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`error_code` VARCHAR(80) CHARACTER SET ascii NOT NULL,`failure_summary_json` JSON NOT NULL,`status` ENUM('open','replayed') NOT NULL,`replayed_by` CHAR(36) CHARACTER SET ascii NULL,`replay_reason` VARCHAR(500) NULL,`replayed_at` DATETIME(3) NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_collection_dead_letter_task` (`task_id`),KEY `idx_collection_dead_scope_status` (`organization_id`,`workspace_id`,`status`,`created_at`),CONSTRAINT `fk_collection_dead_task` FOREIGN KEY (`task_id`) REFERENCES `collection_tasks` (`id`) ON DELETE CASCADE,CONSTRAINT `fk_collection_dead_attempt` FOREIGN KEY (`attempt_id`) REFERENCES `collection_task_attempts` (`id`),CONSTRAINT `fk_collection_dead_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),CONSTRAINT `fk_collection_dead_workspace` FOREIGN KEY (`workspace_id`) REFERENCES `workspaces` (`id`),CONSTRAINT `fk_collection_dead_replayer` FOREIGN KEY (`replayed_by`) REFERENCES `users` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `collection_task_events` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`task_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`event_type` VARCHAR(100) CHARACTER SET ascii NOT NULL,`from_status` VARCHAR(40) CHARACTER SET ascii NULL,`to_status` VARCHAR(40) CHARACTER SET ascii NOT NULL,`actor_type` ENUM('user','worker','crawler','system') NOT NULL,`actor_id` VARCHAR(160) CHARACTER SET ascii NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`metadata_json` JSON NOT NULL,`occurred_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),KEY `idx_collection_event_scope_time` (`organization_id`,`workspace_id`,`occurred_at`),KEY `idx_collection_event_task_time` (`task_id`,`occurred_at`),KEY `idx_collection_event_trace` (`trace_id`),CONSTRAINT `fk_collection_event_task` FOREIGN KEY (`task_id`) REFERENCES `collection_tasks` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `collection_task_outbox` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`task_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`event_type` VARCHAR(100) CHARACTER SET ascii NOT NULL,`payload_json` JSON NOT NULL,`status` ENUM('queued','leased','published','dead_letter') NOT NULL,`attempt_count` TINYINT UNSIGNED NOT NULL DEFAULT 0,`available_at` DATETIME(3) NOT NULL,`lease_owner` VARCHAR(160) CHARACTER SET ascii NULL,`lease_expires_at` DATETIME(3) NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),KEY `idx_collection_outbox_ready` (`status`,`available_at`),KEY `idx_collection_outbox_scope` (`organization_id`,`workspace_id`,`created_at`),CONSTRAINT `fk_collection_outbox_task` FOREIGN KEY (`task_id`) REFERENCES `collection_tasks` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `collection_task_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route` VARCHAR(200) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(255) CHARACTER SET ascii NOT NULL,`task_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_task_id` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_collection_task_operation` (`actor_id`,`route`,`idempotency_key`),CONSTRAINT `fk_collection_operation_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`),CONSTRAINT `fk_collection_operation_task` FOREIGN KEY (`task_id`) REFERENCES `collection_tasks` (`id`) ON DELETE CASCADE,CONSTRAINT `fk_collection_operation_result` FOREIGN KEY (`result_task_id`) REFERENCES `collection_tasks` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
